export const TABLE_VIEWER_CSS = "/* Generated from meatsack-brand. Do not edit. */\n/* product: show; accent: kelp; darkMode: class */\n\n:root {\n  color-scheme: light;\n  --background: oklch(0.975 0.01 90);\n  --foreground: oklch(0.22 0.02 55);\n  --card: oklch(0.995 0.006 90);\n  --card-foreground: oklch(0.22 0.02 55);\n  --muted: oklch(0.94 0.015 90);\n  --muted-foreground: oklch(0.48 0.02 55);\n  --border: oklch(0.88 0.02 80);\n  --machine: oklch(0.26 0.012 250);\n  --machine-raised: oklch(0.3 0.012 250);\n  --machine-foreground: oklch(0.88 0.012 250);\n  --machine-muted: oklch(0.66 0.015 250);\n  --machine-rule: oklch(0.36 0.014 250);\n  --primary: oklch(0.44 0.09 175);\n  --primary-foreground: oklch(0.98 0.01 90);\n  --radius: 0.75rem;\n}\n\nhtml.dark,\n.dark {\n  color-scheme: dark;\n  --background: oklch(0.2 0.012 80);\n  --foreground: oklch(0.96 0.01 90);\n  --card: oklch(0.24 0.012 80);\n  --card-foreground: oklch(0.96 0.01 90);\n  --muted: oklch(0.28 0.012 80);\n  --muted-foreground: oklch(0.74 0.02 80);\n  --border: oklch(1 0 0 / 12%);\n  --machine: oklch(0.17 0.012 250);\n  --machine-raised: oklch(0.21 0.012 250);\n  --machine-foreground: oklch(0.88 0.012 250);\n  --machine-muted: oklch(0.62 0.015 250);\n  --machine-rule: oklch(0.28 0.014 250);\n  --primary: oklch(0.78 0.11 172);\n  --primary-foreground: oklch(0.2 0.012 80);\n}\n\n.meatsack-pulse {\n  left: 50%;\n  top: 0;\n  margin-left: -4.5px;\n  animation: meatsack-travel-y 4.2s cubic-bezier(0.6, 0, 0.4, 1) infinite;\n}\n\n@media (min-width: 1024px) {\n  .meatsack-pulse {\n    left: 0;\n    top: 50%;\n    margin-left: 0;\n    margin-top: -4.5px;\n    animation-name: meatsack-travel-x;\n  }\n}\n\n@keyframes meatsack-travel-x {\n  0% {\n    left: -4px;\n    opacity: 0;\n  }\n  8% {\n    opacity: 1;\n  }\n  42% {\n    left: calc(100% - 5px);\n    opacity: 1;\n  }\n  50% {\n    left: calc(100% - 5px);\n    opacity: 0;\n  }\n  58% {\n    left: calc(100% - 5px);\n    opacity: 1;\n  }\n  92% {\n    left: -4px;\n    opacity: 1;\n  }\n  100% {\n    left: -4px;\n    opacity: 0;\n  }\n}\n\n@keyframes meatsack-travel-y {\n  0% {\n    top: -4px;\n    opacity: 0;\n  }\n  8% {\n    opacity: 1;\n  }\n  42% {\n    top: calc(100% - 5px);\n    opacity: 1;\n  }\n  50% {\n    top: calc(100% - 5px);\n    opacity: 0;\n  }\n  58% {\n    top: calc(100% - 5px);\n    opacity: 1;\n  }\n  92% {\n    top: -4px;\n    opacity: 1;\n  }\n  100% {\n    top: -4px;\n    opacity: 0;\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .meatsack-pulse {\n    animation: none;\n    left: 50%;\n    top: 50%;\n    margin-left: -4.5px;\n    margin-top: -4.5px;\n    opacity: 1;\n  }\n}\n* {\n  box-sizing: border-box;\n}\nhtml,\nbody,\n#root {\n  height: 100%;\n  margin: 0;\n}\nbody {\n  font-family: Geist, ui-sans-serif, system-ui, sans-serif;\n  background: var(--background);\n  color: var(--foreground);\n  font-size: 14px;\n  font-variant-numeric: tabular-nums;\n}\nbutton,\ninput,\nselect {\n  font: inherit;\n  color: inherit;\n}\nbutton,\na,\ninput,\nselect,\nsummary {\n  outline-offset: 3px;\n}\n:focus-visible {\n  outline: 2px solid var(--primary);\n}\n::selection {\n  background: var(--primary);\n  color: var(--primary-foreground);\n}\nbutton,\nsummary {\n  cursor: pointer;\n}\nbutton:disabled {\n  opacity: 0.45;\n  cursor: default;\n}\na {\n  color: var(--primary);\n  text-underline-offset: 3px;\n}\nbutton {\n  background: transparent;\n  border: 1px solid var(--border);\n  border-radius: 5px;\n  padding: 7px 10px;\n}\nbutton:hover:not(:disabled) {\n  background: var(--muted);\n}\ninput,\nselect {\n  background: var(--card);\n  border: 1px solid var(--border);\n  border-radius: 5px;\n  padding: 7px 10px;\n  caret-color: var(--primary);\n}\ninput::placeholder {\n  color: var(--muted-foreground);\n}\n.workbook {\n  height: 100dvh;\n  display: flex;\n  flex-direction: column;\n}\n.workbook-header {\n  padding: 22px 28px;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 20px;\n  border-bottom: 1px solid var(--border);\n}\n.wordmark {\n  font-weight: 650;\n  font-size: 12px;\n  text-decoration: none;\n}\n.workbook-header h1 {\n  font-size: 24px;\n  letter-spacing: -0.025em;\n  line-height: 1.2;\n  margin: 6px 0 0;\n  overflow-wrap: anywhere;\n}\n.download {\n  white-space: nowrap;\n  text-decoration: none;\n  font-weight: 550;\n  padding: 9px 13px;\n  background: var(--card);\n  border: 1px solid var(--border);\n  border-radius: 6px;\n}\n.download:hover {\n  background: var(--muted);\n}\n.sheet-stack {\n  flex: 1;\n  min-height: 0;\n  position: relative;\n}\n.sheet {\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n}\n.sheet[hidden] {\n  display: none;\n}\n.toolbar {\n  display: flex;\n  align-items: end;\n  gap: 16px;\n  padding: 16px 28px;\n  border-bottom: 1px solid var(--border);\n}\n.toolbar label > span {\n  display: block;\n  font-size: 11px;\n  font-weight: 600;\n  color: var(--muted-foreground);\n  margin-bottom: 5px;\n}\n.search {\n  width: min(300px, 35vw);\n}\n.search input {\n  width: 100%;\n}\n.dimensions {\n  margin: 0 0 8px auto;\n  color: var(--muted-foreground);\n  white-space: nowrap;\n  font-size: 12px;\n}\n.column-menu {\n  position: relative;\n}\n.column-menu summary {\n  border: 1px solid var(--border);\n  border-radius: 5px;\n  padding: 7px 10px;\n}\n.column-menu > div {\n  position: absolute;\n  top: 42px;\n  right: 0;\n  width: 240px;\n  max-height: 360px;\n  overflow: auto;\n  z-index: 20;\n  background: var(--card);\n  box-shadow: 0 8px 24px #0002;\n  padding: 12px;\n  border-radius: 8px;\n}\n.column-menu label {\n  display: flex;\n  gap: 8px;\n  align-items: center;\n  padding: 5px;\n  overflow-wrap: anywhere;\n}\n.grid-scroll {\n  overflow: auto;\n  flex: 1;\n  min-height: 0;\n  scrollbar-color: var(--border) var(--background);\n  scrollbar-width: thin;\n  background: var(--card);\n}\n.grid-header {\n  position: sticky;\n  top: 0;\n  height: 74px;\n  z-index: 5;\n  background: var(--muted);\n  border-bottom: 1px solid var(--border);\n  display: flex;\n}\n.column-header {\n  height: 74px;\n  flex-shrink: 0;\n  display: inline-flex;\n  flex-direction: column;\n  padding: 5px 10px 8px;\n  background: var(--muted);\n  border-right: 1px solid var(--border);\n}\n.sort {\n  display: flex;\n  justify-content: space-between;\n  gap: 6px;\n  align-items: center;\n  border: 0;\n  border-radius: 0;\n  padding: 4px 0 7px;\n  text-align: left;\n  font-size: 12px;\n  font-weight: 650;\n  min-width: 0;\n}\n.sort span {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.column-header input {\n  font-size: 12px;\n  min-width: 0;\n  padding: 4px 6px;\n  background: var(--card);\n}\n.resize {\n  position: absolute;\n  right: -3px;\n  top: 0;\n  width: 7px;\n  height: 100%;\n  cursor: col-resize;\n  touch-action: none;\n  z-index: 5;\n}\n.resize:hover,\n.resize:focus {\n  background: var(--primary);\n}\n.row-number {\n  position: sticky;\n  left: 0;\n  width: 48px;\n  flex-shrink: 0;\n  z-index: 3;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  height: 100%;\n  font-size: 11px;\n  color: var(--muted-foreground);\n  background: var(--muted);\n  border-right: 1px solid var(--border);\n  border-bottom: 1px solid var(--border);\n}\n.header-number {\n  height: 74px;\n}\n.grid-row {\n  display: flex;\n  background: var(--card);\n}\n.grid-row.alternate {\n  background: var(--background);\n}\n.cell {\n  height: 36px;\n  flex-shrink: 0;\n  display: inline-block;\n  text-align: left;\n  background: inherit;\n  border: 0;\n  border-right: 1px solid var(--border);\n  border-bottom: 1px solid var(--border);\n  border-radius: 0;\n  padding: 8px 10px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  font-size: 13px;\n}\n.pinned {\n  background: var(--background);\n  box-shadow: 1px 0 0 var(--border);\n}\n.column-header.pinned {\n  background: var(--muted);\n}\n.cell.selected {\n  background: var(--muted);\n  box-shadow: inset 0 0 0 2px var(--primary);\n}\n.empty-cell {\n  color: var(--muted-foreground);\n}\n.cell-detail {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 10px 28px;\n  min-height: 54px;\n  max-height: 140px;\n  border-top: 1px solid var(--border);\n  font-size: 12px;\n}\n.cell-detail p {\n  margin: 0;\n  overflow: auto;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n  flex: 1;\n}\n.cell-address {\n  color: var(--muted-foreground);\n  max-width: 220px;\n  flex-shrink: 0;\n  overflow-wrap: anywhere;\n}\n.cell-detail button {\n  white-space: nowrap;\n}\n.cell-detail > span[role=\"status\"] {\n  color: var(--primary);\n}\nfooter {\n  display: flex;\n  align-items: center;\n  border-top: 1px solid var(--border);\n  padding: 0 28px;\n  min-height: 50px;\n  gap: 16px;\n}\nfooter nav {\n  display: flex;\n  overflow-x: auto;\n  align-self: stretch;\n  gap: 4px;\n  flex: 1;\n}\nfooter button {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  white-space: nowrap;\n  border: 0;\n  border-radius: 0;\n  border-bottom: 2px solid transparent;\n  padding: 13px 14px;\n}\nfooter button[aria-current] {\n  color: var(--primary);\n  border-bottom-color: var(--primary);\n  background: var(--muted);\n  font-weight: 650;\n}\nfooter button span {\n  font-size: 11px;\n  color: var(--muted-foreground);\n}\n.read-only {\n  font-size: 11px;\n  color: var(--muted-foreground);\n  white-space: nowrap;\n}\n.opening {\n  padding: 48px 28px;\n  max-width: 720px;\n}\n.opening h1,\n.opening h2,\n.empty-state h2 {\n  font-size: 24px;\n  letter-spacing: -0.025em;\n}\n.opening p,\n.empty-state p {\n  color: var(--muted-foreground);\n  line-height: 1.6;\n}\n.empty-state {\n  position: sticky;\n  left: 0;\n  padding: 30px 28px;\n  width: min(100%, 500px);\n}\n@media (prefers-color-scheme: dark) {\n  :root {\n    --background: oklch(0.2 0.012 80);\n    --foreground: oklch(0.96 0.01 90);\n    --card: oklch(0.24 0.012 80);\n    --muted: oklch(0.28 0.012 80);\n    --muted-foreground: oklch(0.74 0.02 80);\n    --border: oklch(1 0 0 / 12%);\n    --primary: oklch(0.78 0.11 172);\n    --primary-foreground: oklch(0.2 0.012 80);\n    color-scheme: dark;\n  }\n}\n@media (max-width: 700px) {\n  .workbook-header {\n    padding: 16px;\n    align-items: start;\n  }\n  .workbook-header h1 {\n    font-size: 20px;\n  }\n  .download {\n    font-size: 12px;\n    padding: 7px 9px;\n  }\n  .toolbar {\n    padding: 12px 16px;\n    gap: 10px;\n    flex-wrap: wrap;\n  }\n  .search {\n    width: calc(100% - 140px);\n    flex-grow: 1;\n  }\n  .dimensions {\n    order: 5;\n    width: 100%;\n    margin: 0;\n  }\n  .reset {\n    margin-left: auto;\n  }\n  .cell-detail {\n    padding: 10px 16px;\n    flex-wrap: wrap;\n  }\n  .cell-address {\n    max-width: 100%;\n    width: 100%;\n  }\n  .cell-detail p {\n    max-height: 44px;\n  }\n  footer {\n    padding: 0 8px;\n  }\n  .read-only {\n    display: none;\n  }\n}\n\n.preview-scroll {\n  overflow: auto;\n}\n.preview-table {\n  border-collapse: collapse;\n  width: 100%;\n  font-size: 13px;\n}\n.preview-table th,\n.preview-table td {\n  padding: 9px 12px;\n  border: 1px solid var(--border);\n  text-align: left;\n  max-width: 240px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.preview-table th {\n  background: var(--muted);\n}\n";
